int rfcomm_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                  size_t size, int flags)
{
    int bytes_received = 0;

    /* Check and handle deferred RFCOMM connection setup if needed */
    if (sock->sk->sk_state == BT_CONFIG) {
        bt_accept_connection(sock);
    }

    /* Call lower-level function to receive the message */
    bytes_received = sock->sk->sk_data_recv(iocb, sock, msg, size, flags);

    if (bytes_received > 0) {
        /* Update socket's receive memory allocation */
        sock->sk->sk_rmem_alloc += bytes_received;

        /* Check if memory usage is below a threshold to unthrottle */
        if (sock->sk->sk_rmem_alloc < RFCOMM_RECV_THRESHOLD) {
            bt_unthrottle_connection(sock);
        }
    }

    return bytes_received;
}

int rfcomm_receive_message(struct kiocb *iocb, struct socket *sock,
                           struct msghdr *msg, size_t size, int flags)
{
    int bytes_received;

    /* Check if RFCOMM connection setup is deferred and accept it if needed */
    if (rfcomm_connection_deferred(sock)) {
        rfcomm_accept_connection(sock);
    }

    /* Call lower-level function to receive message */
    bytes_received = sock->ops->recvmsg(iocb, msg, size, flags);

    if (bytes_received > 0) {
        /* Update socket's receive memory allocation */
        sock_update_rcv_mem(sock, bytes_received);

        /* Unthrottle the connection if memory usage is below the threshold */
        if (sock_rcv_mem_usage(sock) < RFCOMM_RCV_MEM_THRESHOLD) {
            rfcomm_unthrottle_connection(sock);
        }
    }

    return bytes_received;
}

#include <linux/socket.h>
#include <linux/ioctl.h>
#include <net/sock.h>

int handle_rfcomm_recv(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                      size_t size, int flags) {
    int bytes_received;

    if (test_bit(SOCK_ZAPPED, &sock->sk->sk_flags))
        return 0;

    if (rfcomm_is_setup_deferred(sock->sk)) {
        rfcomm_accept_connection(sock->sk);
    }

    bytes_received = sock->sk->sk_prot->recvmsg(iocb, msg, size, flags);
    if (bytes_received > 0) {
        sock_update_memalloc(sock->sk, bytes_received);
        if (sk_rmem_free_get(sock->sk) < sock->sk->sk_rcvbuf / 2) {
            rfcomm_unthrottle_connection(sock->sk);
        }
    } else if (bytes_received == 0) {
        return 0;
    }

    return bytes_received;
}

